<!doctype html><html lang="{{ app()->getLocale() }}" dir="{{ str_starts_with(app()->getLocale(), 'ar') ? 'rtl' : 'ltr' }}"><head><meta charset="utf-8"><title>{{ __('Gift Receipt') }} {{ $receipt->reference }}</title><style>body{font-family:Arial,sans-serif;margin:2rem;color:#111}.receipt{max-width:34rem;margin:auto}.muted{color:#555}.line{display:flex;justify-content:space-between;border-bottom:1px solid #ddd;padding:.55rem 0}.item{display:flex;flex-direction:column}@media print{body{margin:.5rem}}</style></head><body><main class="receipt"><h1>{{ __('Gift Receipt') }}</h1><p class="muted">{{ __('Price-free return reference') }}</p><p><strong>{{ __('Reference') }}:</strong> {{ $receipt->reference }}</p><p><strong>{{ __('Original sale') }}:</strong> {{ $receipt->sale?->document_number ?: '#'.$receipt->sale_id }}</p><p><strong>{{ __('Print') }}:</strong> {{ $event->is_reprint ? __('Reprint') : __('Original') }}</p><h2>{{ __('Eligible items') }}</h2>@foreach($receipt->lines as $line)<div class="line"><span class="item"><span>{{ str_starts_with(app()->getLocale(), 'ar') ? $line->name_ar : $line->name_en }}</span><small>{{ $line->item_code }}</small><x-variant-snapshot :snapshot="$line->saleLine?->variant_snapshot" /></span><span><x-product-quantity :value="$line->quantity" /></span></div>@endforeach<p class="muted">{{ __('Prices, discounts, tax, totals, payment details, and hidden price metadata are intentionally omitted.') }}</p><p>{{ __('Present this reference to validate an eligible return.') }}</p></main><script>window.addEventListener('load',()=>window.print())</script></body></html>
